From cf93421d84b6abac903d8b724542a17be0287ca5 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 05:03:12 +0100
Subject: [PATCH] libtaskmanager: allow keeping transient windows in a filtered
 model

Transient windows such as dialogs are always filtered out as skip-taskbar
tasks, so models looking for windows in a region cannot see them. Add an
IsTransient role and a filterTransients property to let them through.

BUG: 523220
---
 libtaskmanager/abstracttasksmodel.cpp     |  1 +
 libtaskmanager/abstracttasksmodel.h       |  2 ++
 libtaskmanager/taskfilterproxymodel.cpp   | 20 +++++++++++++++++++-
 libtaskmanager/taskfilterproxymodel.h     | 22 ++++++++++++++++++++++
 libtaskmanager/taskgroupingproxymodel.cpp |  2 ++
 libtaskmanager/tasksmodel.cpp             | 11 +++++++++++
 libtaskmanager/tasksmodel.h               | 22 ++++++++++++++++++++++
 libtaskmanager/waylandtasksmodel.cpp      |  8 +++++---
 8 files changed, 84 insertions(+), 4 deletions(-)

diff --git a/libtaskmanager/abstracttasksmodel.cpp b/libtaskmanager/abstracttasksmodel.cpp
index 4285e99393..0ce304b8e9 100644
--- a/libtaskmanager/abstracttasksmodel.cpp
+++ b/libtaskmanager/abstracttasksmodel.cpp
@@ -100,6 +100,7 @@ QVariant AbstractTasksModel::data(const QModelIndex &, int role) const
     case CanSetNoBorder:
     case HasNoBorder:
     case IsExcludedFromCapture:
+    case IsTransient:
         return false;
     case StorageId:
         return QString();
diff --git a/libtaskmanager/abstracttasksmodel.h b/libtaskmanager/abstracttasksmodel.h
index cb6c38f998..33d1c30a7a 100644
--- a/libtaskmanager/abstracttasksmodel.h
+++ b/libtaskmanager/abstracttasksmodel.h
@@ -96,6 +96,8 @@ public:
         IsExcludedFromCapture, /**< Whether the task's window has been hidden from screencasts. @since 6.6 */
         StorageId, /** The KService storageId for the underlying service. @since 6.8  */
         IsMapped, /**< Whether the window is mapped, @since 6.8 */
+        IsTransient, /**< Task (i.e. window) is a transient window, such as a dialog, that is
+                          omitted from 'task bars' only because of that. @since 6.9 */
     };
     Q_ENUM(AdditionalRoles)

diff --git a/libtaskmanager/taskfilterproxymodel.cpp b/libtaskmanager/taskfilterproxymodel.cpp
index 4139ad787d..f6f953d106 100644
--- a/libtaskmanager/taskfilterproxymodel.cpp
+++ b/libtaskmanager/taskfilterproxymodel.cpp
@@ -40,6 +40,7 @@ public:
     bool filterNotMaximized = false;
     bool filterHidden = false;
     bool filterSkipTaskbar = true;
+    bool filterTransients = true;
     bool filterSkipPager = false;

     bool demandingAttentionSkipsFilters = true;
@@ -322,6 +323,22 @@ void TaskFilterProxyModel::setFilterHidden(bool filter)
     }
 }

+bool TaskFilterProxyModel::filterTransients() const
+{
+    return d->filterTransients;
+}
+
+void TaskFilterProxyModel::setFilterTransients(bool filter)
+{
+    if (d->filterTransients != filter) {
+        d->filterTransients = filter;
+
+        invalidateFilter();
+
+        Q_EMIT filterTransientsChanged();
+    }
+}
+
 bool TaskFilterProxyModel::filterSkipTaskbar() const
 {
     return d->filterSkipTaskbar;
@@ -401,7 +418,8 @@ bool TaskFilterProxyModel::acceptsRow(int sourceRow) const
     }

     // Filter tasks that are not to be shown on the task bar.
-    if (d->filterSkipTaskbar && sourceIdx.data(AbstractTasksModel::SkipTaskbar).toBool()) {
+    if (d->filterSkipTaskbar && sourceIdx.data(AbstractTasksModel::SkipTaskbar).toBool()
+        && (d->filterTransients || !sourceIdx.data(AbstractTasksModel::IsTransient).toBool())) {
         return false;
     }

diff --git a/libtaskmanager/taskfilterproxymodel.h b/libtaskmanager/taskfilterproxymodel.h
index e37c071159..c3a81017af 100644
