+     *
+     * @see setFilterTransients
+     * @returns @c true if transient windows should be filtered.
+     * @since 6.9
+     **/
+    bool filterTransients() const;
+
+    /**
+     * Set whether transient windows, such as dialogs, should be filtered
+     * along with other tasks omitted from 'task bars'.
+     *
+     * @see filterTransients
+     * @param filter Whether transient windows should be filtered.
+     * @since 6.9
+     **/
+    void setFilterTransients(bool filter);
+
     /**
      * Whether tasks which should be omitted from 'task bars' should be
      * filtered. Defaults to @c true.
@@ -421,6 +442,7 @@ Q_SIGNALS:
     void filterNotMinimizedChanged() const;
     void filterNotMaximizedChanged() const;
     void filterHiddenChanged() const;
+    void filterTransientsChanged() const;
     void filterSkipTaskbarChanged() const;
     void filterSkipPagerChanged() const;
     void demandingAttentionSkipsFiltersChanged() const;
diff --git a/libtaskmanager/taskgroupingproxymodel.cpp b/libtaskmanager/taskgroupingproxymodel.cpp
index 82709a40c9..f16a6734f3 100644
--- a/libtaskmanager/taskgroupingproxymodel.cpp
+++ b/libtaskmanager/taskgroupingproxymodel.cpp
@@ -725,6 +725,8 @@ QVariant TaskGroupingProxyModel::data(const QModelIndex &proxyIndex, int role) c
             return d->all(proxyIndex, AbstractTasksModel::IsExcludedFromCapture);
         case AbstractTasksModel::IsMapped:
