     groupingProxyModel = new TaskGroupingProxyModel(q);
@@ -1188,6 +1189,16 @@ void TasksModel::setFilterHidden(bool filter)
     d->filterProxyModel->setFilterHidden(filter);
 }

+bool TasksModel::filterTransients() const
+{
+    return d->filterProxyModel->filterTransients();
+}
+
+void TasksModel::setFilterTransients(bool filter)
